INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs) VALUES ('p45', 'ru', 'Корзина «Декор»', 'Корзины и сундуки', 'Сундук и корзина для белья из искусственного ротанга с мягкой тканевой подкладкой и крышкой. Держит форму, не цепляет ткань и проветривается — для хранения белья, пледов, игрушек и мелочей в спальне или ванной.', '["S","M","L"]', '{"mat":"Искусственный ротанг + подкладка","dim":"С крышкой и подкладкой","fin":"Гладкое плетение","wt":"Складная подкладка","seat":"Бельё, пледы, хранение","made":"Ташкент, ручная работа"}');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs) VALUES ('p45', 'uz', '«Dekor» savat', 'Savat va sandiq', 'Sun’iy rotangdan yumshoq mato astarli va qopqoqli sandiq hamda kir savati. Shaklini saqlaydi, matoga ilashmaydi va shamollatiladi — yotoqxona yoki hammomda kir, pled, o‘yinchoq va mayda buyumlar uchun.', '["S","M","L"]', '{"mat":"Sun’iy rotang + astar","dim":"Qopqoq va astar bilan","fin":"Silliq to‘quv","wt":"Yig‘iladigan astar","seat":"Kir, pled, saqlash","made":"Toshkent, qo‘l mehnati"}');
INSERT OR REPLACE INTO product_i18n (product_id, lang, name, category_label, description, sizes, specs) VALUES ('p45', 'en', 'Décor Basket', 'Baskets & chests', 'A chest and laundry basket in synthetic rattan with a soft fabric liner and lid. Holds its shape, won''t snag fabric and stays ventilated — for laundry, throws, toys and bits in the bedroom or bathroom.', '["S","M","L"]', '{"mat":"Synthetic rattan + liner","dim":"With lid & liner","fin":"Smooth weave","wt":"Foldable liner","seat":"Laundry, throws, storage","made":"Tashkent, by hand"}');

